21|  /** Rounds half away from zero, on the exact binary value. */
22|  static double round(double x) {
23|    if (Double.isNaN(x) || Double.isInfinite(x)) {
24|      return x;
25|    }
26|    double r = new BigDecimal(x).setScale(0, RoundingMode.HALF_UP).doubleValue();
27|    return (r == 0 && (x < 0 || 1 / x < 0)) ? -0.0 : r;
28|  }
29|
30|  /** Rounds a monetary amount to cents. */
31|  static double round2(double f) {
32|    return round(f * 100) / 100;
33|  }
34|
35|  /** Fixed-point with prec decimals, rounded half-to-even on the exact binary value. */
36|  static String fixed(double x, int prec) {
37|    if (Double.isNaN(x)) return "NaN";
38|    if (Double.isInfinite(x)) return x > 0 ? "+Inf" : "-Inf";
39|    String s = new BigDecimal(x).setScale(prec, RoundingMode.HALF_EVEN).toPlainString();
40|    boolean neg = x < 0 || (x == 0 && 1 / x < 0);
41|    if (neg && !s.startsWith("-")) s = "-" + s;
42|    return s;
43|  }
