45|  /** Dollar format with thousands separators, e.g. $1,234,567.89. */
46|  static String usd(double f) {
47|    String s = fixed(f, 2);
48|    String intPart = s.substring(0, s.length() - 3), dec = s.substring(s.length() - 3);
49|    String neg = "";
50|    if (!intPart.isEmpty() && intPart.charAt(0) == '-') {
51|      neg = "-";
52|      intPart = intPart.substring(1);
53|    }
54|    StringBuilder out = new StringBuilder();
55|    for (int i = 0; i < intPart.length(); i++) {
56|      if (i > 0 && (intPart.length() - i) % 3 == 0) {
57|        out.append(',');
58|      }
59|      out.append(intPart.charAt(i));
60|    }
61|    return neg + "$" + out + dec;
62|  }
