69|  private static String shortestExp(double x) {
70|    if (x == 0) return ((1 / x < 0) ? "-" : "") + "0e+00";
71|    BigDecimal bd = new BigDecimal(Double.toString(x)).stripTrailingZeros();
72|    String digits = bd.unscaledValue().abs().toString();
73|    int exp = digits.length() - 1 - bd.scale();
74|    StringBuilder sb = new StringBuilder();
75|    if (bd.signum() < 0) sb.append('-');
76|    sb.append(digits.charAt(0));
77|    if (digits.length() > 1) sb.append('.').append(digits, 1, digits.length());
78|    sb.append('e').append(exp < 0 ? '-' : '+');
79|    int a = Math.abs(exp);
