101|  /** Interpolates verbs %s %v %d %f %%, the - 0 + flags, width and precision. */
102|  static String sprintf(String format, Object... args) {
103|    StringBuilder out = new StringBuilder();
104|    int argi = 0;
105|    int n = format.length();
106|    for (int i = 0; i < n; i++) {
107|      char c = format.charAt(i);
108|      if (c != '%') {
109|        out.append(c);
110|        continue;
111|      }
112|      i++;
113|      if (i >= n) {
114|        out.append("%!(NOVERB)");
115|        break;
116|      }
117|      boolean minus = false, zero = false, plus = false;
118|      for (; i < n; i++) {
119|        char f = format.charAt(i);
120|        if (f == '-') minus = true;
121|        else if (f == '0') zero = !minus;
122|        else if (f == '+') plus = true;
123|        else break;
124|      }
125|      int width = -1;
126|      int start = i;
127|      while (i < n && Character.isDigit(format.charAt(i))) i++;
128|      if (i > start) width = Integer.parseInt(format.substring(start, i));
129|      int prec = -1;
130|      if (i < n && format.charAt(i) == '.') {
131|        i++;
132|        start = i;
133|        while (i < n && Character.isDigit(format.charAt(i))) i++;
134|        prec = i > start ? Integer.parseInt(format.substring(start, i)) : 0;
135|      }
136|      if (i >= n) {
137|        out.append("%!(NOVERB)");
138|        break;
139|      }
140|      char verb = format.charAt(i);
141|      if (verb == '%') {
142|        out.append('%');
143|        continue;
144|      }
145|      if (argi >= args.length) {
146|        out.append("%!").append(verb).append("(MISSING)");
147|        continue;
148|      }
149|      Object arg = args[argi++];
150|      String s;
151|      boolean numeric = false;
152|      switch (verb) {
153|        case 'd' -> {
154|          numeric = true;
155|          s = (arg instanceof Number num) ? Long.toString(num.longValue()) : "%!d(" + v(arg) + ")";
156|          if (plus && arg instanceof Number num && num.longValue() >= 0) s = "+" + s;
157|        }
158|        case 'f' -> {
159|          numeric = true;
160|          s = (arg instanceof Number num) ? fixed(num.doubleValue(), prec < 0 ? 6 : prec) : "%!f(" + v(arg) + ")";
161|          if (plus && !s.startsWith("-")) s = "+" + s;
162|        }
163|        case 's', 'v' -> {
164|          s = v(arg);
165|          if (prec >= 0 && verb == 's' && s.length() > prec) s = s.substring(0, prec);
166|        }
167|        default -> s = "%!" + verb + "(" + v(arg) + ")";
168|      }
169|      out.append(pad(s, width, minus, zero && numeric));
170|    }
171|    return out.toString();
172|  }
