174|  private static String pad(String s, int width, boolean left, boolean zero) {
175|    int len = s.codePointCount(0, s.length());
176|    if (width < 0 || len >= width) return s;
177|    int fill = width - len;
178|    if (left) {
179|      return s + " ".repeat(fill);
180|    }
181|    if (zero) {
182|      if (s.startsWith("-") || s.startsWith("+")) {
183|        return s.charAt(0) + "0".repeat(fill) + s.substring(1);
184|      }
185|      return "0".repeat(fill) + s;
186|    }
187|    return " ".repeat(fill) + s;
188|  }
189|
190|  static String v(Object o) {
191|    if (o == null) return "<nil>";
192|    if (o instanceof Double d) return gFloat(d);
193|    if (o instanceof Float f) return gFloat(f);
194|    if (o instanceof Collection<?> c) {
195|      StringBuilder sb = new StringBuilder("[");
196|      boolean first = true;
197|      for (Object e : c) {
198|        if (!first) sb.append(' ');
199|        sb.append(v(e));
200|        first = false;
201|      }
202|      return sb.append(']').toString();
203|    }
204|    if (o instanceof Map<?, ?> m) {
205|      StringBuilder sb = new StringBuilder("map[");
206|      boolean first = true;
207|      for (Map.Entry<?, ?> e : new TreeMap<>(m).entrySet()) {
208|        if (!first) sb.append(' ');
209|        sb.append(v(e.getKey())).append(':').append(v(e.getValue()));
210|        first = false;
211|      }
212|      return sb.append(']').toString();
213|    }
214|    return o.toString();
215|  }
216|
217|  static String slice(List<String> l) {
218|    return v(l == null ? List.of() : l);
219|  }
