9|
10|/** Tiny dependency-free PDF 1.4 generator (Helvetica / Courier text only), A4 pages. */
11|final class Pdf {
12|  private record Line(String text, String font, double size, double gap) {}
13|
14|  private final List<Line> lines = new ArrayList<>();
15|
16|  void title(String s) {
17|    lines.add(new Line(s, "F2", 16, 6));
18|  }
19|
20|  void heading(String s) {
21|    lines.add(new Line(s, "F2", 11, 10));
22|  }
23|
24|  void text(String s) {
25|    lines.add(new Line(s, "F1", 9.5, 0));
26|  }
27|
28|  void mono(String s) {
29|    lines.add(new Line(s, "F3", 8.5, 0));
30|  }
31|
32|  /** Keeps to WinAnsi-safe ASCII and escapes PDF string delimiters. */
33|  static String esc(String s) {
34|    StringBuilder b = new StringBuilder();
35|    s.codePoints().forEach(c -> {
36|      if (c > 126) {
37|        switch (c) {
38|          case '—', '–' -> c = '-';
39|          case '≥' -> c = '>';
40|          default -> c = '?';
41|        }
42|      }
43|      switch (c) {
44|        case '\\' -> b.append("\\\\");
45|        case '(' -> b.append("\\(");
46|        case ')' -> b.append("\\)");
47|        default -> b.appendCodePoint(c);
48|      }
49|    });
50|    return b.toString();
51|  }
52|
53|  byte[] bytes() {
54|    final double pageW = 595.0, pageH = 842.0;
55|    final double marginL = 50.0, top = 790.0;
56|    final double bottom = 60.0;
57|    List<String> pages = new ArrayList<>();
58|    StringBuilder cur = new StringBuilder();
59|    double y = top;
60|    int pageNo = 1;
61|    for (Line l : lines) {
62|      double h = l.size * 1.35 + l.gap;
63|      if (y - h < bottom) {
64|        cur.append(footer(marginL, pageNo));
65|        pages.add(cur.toString());
66|        cur.setLength(0);
67|        y = top;
68|        pageNo++;
69|      }
70|      y -= h;
71|      cur.append(sprintf("BT /%s %.1f Tf %.1f %.1f Td (%s) Tj ET\n", l.font, l.size, marginL, y, esc(l.text)));
72|    }
73|    cur.append(footer(marginL, pageNo));
74|    pages.add(cur.toString());
75|
76|    Out out = new Out();
77|    out.raw("%PDF-1.4\n");
78|    out.bytes(new byte[] {'%', (byte) 0xe2, (byte) 0xe3, (byte) 0xcf, (byte) 0xd3, '\n'});
79|    int n = pages.size();
80|    out.obj("<< /Type /Catalog /Pages 2 0 R >>");
81|    List<String> kids = new ArrayList<>();
82|    for (int i = 0; i < n; i++) {
83|      kids.add(sprintf("%d 0 R", 6 + i * 2));
84|    }
85|    out.obj(sprintf("<< /Type /Pages /Kids [%s] /Count %d >>", String.join(" ", kids), n));
86|    out.obj("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>");
87|    out.obj("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>");
88|    out.obj("<< /Type /Font /Subtype /Type1 /BaseFont /Courier /Encoding /WinAnsiEncoding >>");
89|    for (int i = 0; i < n; i++) {
90|      String content = pages.get(i);
91|      out.obj(sprintf("<< /Type /Page /Parent 2 0 R /MediaBox [0 0 %.0f %.0f] /Resources << /Font << /F1 3 0 R /F2 4 0 R /F3 5 0 R >> >> /Contents %d 0 R >>",
92|          pageW, pageH, 7 + i * 2));
93|      out.obj(sprintf("<< /Length %d >>\nstream\n%sendstream", content.getBytes(StandardCharsets.UTF_8).length, content));
94|    }
95|    int xref = out.size();
96|    out.raw(sprintf("xref\n0 %d\n0000000000 65535 f \n", out.offsets.size() + 1));
97|    for (int o : out.offsets) {
98|      out.raw(sprintf("%010d 00000 n \n", o));
99|    }
100|    out.raw(sprintf("trailer\n<< /Size %d /Root 1 0 R >>\nstartxref\n%d\n%%EOF\n", out.offsets.size() + 1, xref));
101|    return out.toByteArray();
102|  }
103|
104|  private static String footer(double marginL, int pageNo) {
105|    return sprintf("BT /F1 8 Tf %.1f %.1f Td (Page %d - Intelligent Capital Call & Liquidity Orchestration - Temporal) Tj ET\n",
106|        marginL, 30.0, pageNo);
107|  }
108|
109|  private static final class Out {
110|    final ByteArrayOutputStream buf = new ByteArrayOutputStream();
111|    final List<Integer> offsets = new ArrayList<>();
112|
113|    void raw(String s) {
114|      bytes(s.getBytes(StandardCharsets.UTF_8));
115|    }
116|
117|    void bytes(byte[] b) {
118|      buf.writeBytes(b);
119|    }
120|
121|    int size() {
122|      return buf.size();
123|    }
124|
125|    void obj(String body) {
126|      offsets.add(buf.size());
127|      raw(sprintf("%d 0 obj\n%s\nendobj\n", offsets.size(), body));
128|    }
129|
130|    byte[] toByteArray() {
131|      return buf.toByteArray();
132|    }
133|  }
134|}
